CREATE DATABASE customer_behaviour;
USE customer_behaviour;
show DATABASES;
show tables;
SELECT * FROM customer LIMIT 20;

--  1. What is the total revenue generated by male vs female customers?
SELECT gender , SUM(purchase_amount_usd) as revenue FROM customer GROUP BY gender;

-- 2. which customers used a discount but still spent more than the avg purchase amount
select customer_id,purchase_amount_usd FROM customer WHERE discount_applied = 'Yes' and  purchase_amount_usd >= (select AVG(purchase_amount_usd) from customer);

-- 3. which are the top 5 products with the highest avg review rating
SELECT item_purchased, ROUND(avg(review_rating),2) as "Average Product Rating" from customer group by item_purchased order by avg(review_rating) desc limit 5;


-- 4. compare the average purchase amounts b/w std and express shipping.
select shipping_type,round(avg(purchase_amount),2) as avg_purchase_amount from customer where shipping_type in ('Standard','Express') group by shipping_type;


-- 5. do subscribed customers spend more? compare avg spend and total revenue b/w subscribers and non subscribers 
SELECT subscription_status, COUNT(customer_id) as total_customer,
ROUND(AVG(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue from customer GROUP BY subscription_status ORDER BY total_revenue,avg_spend DESC; 


-- 6. which 5 products have the highest percentage of purchase with discount applied?
SELECT item_purchased,
       ROUND(SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS discount_rate
FROM customer 
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- 7.segment customers into New,Returning, and loyal based on their total no of previous purchase and show the count of each segment.
WITH customer_type as (select customer_id , previous_purchases,
CASE WHEN previous_purchases =1 THEN 'New'
WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning' ELSE 'Loyal' END as customer_segment FROM customer) 
SELECT customer_segment, COUNT(*) as "number of customers" FROM customer_type GROUP BY customer_segment;


-- 8 what are the top 3 most purchased products with in each category

WITH item_count AS (
    SELECT category,
           item_purchased, 
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank 
    FROM customer 
    GROUP BY category, item_purchased
)
SELECT item_rank, category, item_purchased, total_orders 
FROM item_count 
WHERE item_rank <= 3;

-- 9 Are customers who are repeat buyers (more than 5 previous purchases) also lokely to subscribe?
SELECT subscription_status,
COUNT(customer_id) AS repeat_buyers 
FROM customer
where previous_purchases>5
GROUP BY subscription_status;


-- 10 what is the revenue contribution each age group
select age_group, 
sum(purchase_amount) as total_revenue  from customer GROUP by age_group ORDER BY total_revenue DESC;


